parameters.jsCode:
const data = $json.data || {};

const hits = (key, path) => {
  const node = data[key];
  if (!node) return 0;
  if (path === 'direct') return (node.items || []).length;
  if (path === 'boards') return ((node[0] || {}).items_page || {}).items ? node[0].items_page.items.length : 0;
  return 0;
};

const emailDupContacts = hits('contactsByEmail', 'direct');
const emailDupLeads = hits('leadsByEmail', 'direct');
const nameDupContacts = hits('contactsByName', 'boards');
const nameDupLeads = hits('leadsByName', 'boards');

const is_duplicate = (emailDupContacts + emailDupLeads + nameDupContacts + nameDupLeads) > 0;

return [{
  json: {
    is_duplicate,
    matched_on: {
      email_on_contacts: emailDupContacts > 0,
      email_on_leads: emailDupLeads > 0,
      name_and_company_on_contacts: nameDupContacts > 0,
      name_and_company_on_leads: nameDupLeads > 0
    },
    errors: $json.errors || null
  }
}];
